LESSONS = [{'id': '01-welcome', 'num': 1, 'level': 'beginner', 'level_label': 'Beginner', 'title': 'Welcome & what Ubuntu is', 'summary': 'A friendly intro to Ubuntu for Windows users — what it is, how it feels familiar, and what is different.', 'steps': ['You just installed (or are about to use) Ubuntu — a free operating system, like Windows or macOS, but built on Linux.', 'Ubuntu is made by Canonical and a huge community. Version numbers like 24.04 mean April 2024; 26.04 means April 2026. The .04 releases are long-term support (LTS) — good for everyday use.', 'Think of Ubuntu as: a desktop you can click around, install apps, browse the web, and do office work — same goals as Windows, different tools under the hood.'], 'html_file': 'html/lessons/01-welcome.html', 'keywords': 'welcome & what ubuntu is a friendly intro to ubuntu for windows users — what it is, how it feels familiar, and what is different. beginner you just installed (or are about to use) ubuntu — a free operating system, like windows or macos, but built on linux. ubuntu is made by canonical and a huge community. version numbers like 24.04 mean april 2024; 26.04 means april 2026. the .04 releases are long-term support (lts) — good for everyday use.'}, {'id': '02-desktop', 'num': 2, 'level': 'beginner', 'level_label': 'Beginner', 'title': 'Desktop tour', 'summary': 'Activities, the dock, the top bar, and Settings — your GNOME map.', 'steps': ['Press the Super key (Windows key) or click Activities (top-left) to open the overview. Type an app name to search and launch it.', 'The dock on the left shows favorites and open apps. Right-click an icon → Add to Favorites to pin it.', 'The top bar has the clock (center or left depending on version), and the system menu on the right: Wi‑Fi, Bluetooth, sound, battery, power.', 'Open Settings from the system menu or by searching “Settings” in Activities. Explore Displays, Wi‑Fi, Appearance, and Users — change one thing at a time.'], 'html_file': 'html/lessons/02-desktop.html', 'keywords': 'desktop tour activities, the dock, the top bar, and settings — your gnome map. beginner press the super key (windows key) or click activities (top-left) to open the overview. type an app name to search and launch it. the dock on the left shows favorites and open apps. right-click an icon → add to favorites to pin it.'}, {'id': '03-files', 'num': 3, 'level': 'beginner', 'level_label': 'Beginner', 'title': 'Files app & folders', 'summary': 'Home, Downloads, Trash, and how folders work on Ubuntu.', 'steps': ['Open Files from the dock (folder icon) or search “Files”.', 'In the sidebar: Home is your personal folder. Downloads, Documents, Pictures, Music, Videos are the usual places — same idea as Windows.', 'Delete a file: right-click → Move to Trash. Empty Trash from the sidebar when you are sure.', 'USB drives appear in the sidebar when plugged in. Click the eject icon before unplugging.'], 'html_file': 'html/lessons/03-files.html', 'keywords': 'files app & folders home, downloads, trash, and how folders work on ubuntu. beginner open files from the dock (folder icon) or search “files”. in the sidebar: home is your personal folder. downloads, documents, pictures, music, videos are the usual places — same idea as windows.'}, {'id': '04-install-apps', 'num': 4, 'level': 'beginner', 'level_label': 'Beginner', 'title': 'Installing apps', 'summary': 'App Center / Software, and a gentle intro to Flatpak and Flathub.', 'steps': ['Open App Center (Ubuntu 24.04+) or Ubuntu Software. Search for an app (try “VLC” or “GIMP”).', 'Read the listing. Prefer apps marked as open source / from Ubuntu or Flathub when you have a choice.', 'Click Install. Enter your password if asked. Wait for the progress bar, then launch from Activities.', 'Optional: enable Flathub for more apps — see Lesson 13. Many beginners can stay with App Center first.'], 'html_file': 'html/lessons/04-install-apps.html', 'keywords': 'installing apps app center / software, and a gentle intro to flatpak and flathub. beginner open app center (ubuntu 24.04+) or ubuntu software. search for an app (try “vlc” or “gimp”). read the listing. prefer apps marked as open source / from ubuntu or flathub when you have a choice.'}, {'id': '05-updates', 'num': 5, 'level': 'beginner', 'level_label': 'Beginner', 'title': 'Updates', 'summary': 'Keep Ubuntu healthy with Software Updater and a gentle apt intro.', 'steps': ['When Ubuntu notifies you, open Software Updater. Review the list → Install Now → enter password → restart if asked.', 'You can also open Software Updater anytime from Activities.', 'Optional terminal way (same idea): open Terminal and run the two commands below, one at a time.'], 'html_file': 'html/lessons/05-updates.html', 'keywords': 'updates keep ubuntu healthy with software updater and a gentle apt intro. beginner when ubuntu notifies you, open software updater. review the list → install now → enter password → restart if asked. you can also open software updater anytime from activities.'}, {'id': '06-wifi-bt-display', 'num': 6, 'level': 'beginner', 'level_label': 'Beginner', 'title': 'Wi‑Fi, Bluetooth, displays', 'summary': 'Connect to networks, pair devices, and set resolution / scaling.', 'steps': ['Click the system menu (top-right) → Wi‑Fi → pick your network → enter the password.', 'Bluetooth: system menu or Settings → Bluetooth → turn on → pair headphones or a mouse when they are in pairing mode.', 'Displays: Settings → Displays. Set resolution, orientation, and (on HiDPI screens) scale 100% / 200% until text looks comfortable.', 'Multiple monitors: arrange them in the Displays diagram to match your desk, then Apply.'], 'html_file': 'html/lessons/06-wifi-bt-display.html', 'keywords': 'wi‑fi, bluetooth, displays connect to networks, pair devices, and set resolution / scaling. beginner click the system menu (top-right) → wi‑fi → pick your network → enter the password. bluetooth: system menu or settings → bluetooth → turn on → pair headphones or a mouse when they are in pairing mode.'}, {'id': '07-screenshots', 'num': 7, 'level': 'beginner', 'level_label': 'Beginner', 'title': 'Screenshots, clipboard, shortcuts', 'summary': 'Capture the screen, copy-paste habits, and everyday keyboard shortcuts.', 'steps': ['Press Print Screen (PrtSc) to open the screenshot UI. Choose screen, window, or selection. Save or copy to clipboard.', 'On many Ubuntu GNOME setups, Shift+PrtSc or the screenshot app also works — try PrtSc first.', 'Clipboard: Ctrl+C copy, Ctrl+V paste, Ctrl+X cut — same as Windows in most apps.', 'Learn a few shortcuts below; they save a lot of mouse travel.'], 'html_file': 'html/lessons/07-screenshots.html', 'keywords': 'screenshots, clipboard, shortcuts capture the screen, copy-paste habits, and everyday keyboard shortcuts. beginner press print screen (prtsc) to open the screenshot ui. choose screen, window, or selection. save or copy to clipboard. on many ubuntu gnome setups, shift+prtsc or the screenshot app also works — try prtsc first.'}, {'id': '08-terminal', 'num': 8, 'level': 'comfortable', 'level_label': 'Getting comfortable', 'title': 'Terminal basics', 'summary': 'pwd, ls, cd, and copy-paste — enough to follow guides without fear.', 'steps': ['Open Terminal: Ctrl+Alt+T or search “Terminal”.', 'Type <code>pwd</code> and press Enter — print working directory (where you are).', 'Type <code>ls</code> — list files. Try <code>ls -la</code> for details and hidden files.', 'Type <code>cd Downloads</code> to enter Downloads (if it exists). <code>cd ..</code> goes up one folder. <code>cd</code> alone returns to Home.', 'Copy text from a guide: select → Ctrl+Shift+C in Terminal to copy; Ctrl+Shift+V to paste. Or use the right-click menu.'], 'html_file': 'html/lessons/08-terminal.html', 'keywords': 'terminal basics pwd, ls, cd, and copy-paste — enough to follow guides without fear. getting comfortable open terminal: ctrl+alt+t or search “terminal”. type <code>pwd</code> and press enter — print working directory (where you are).'}, {'id': '09-sudo', 'num': 9, 'level': 'comfortable', 'level_label': 'Getting comfortable', 'title': 'Safe vs sudo / password prompts', 'summary': 'When Ubuntu asks for your password, what sudo means, and how to stay safe.', 'steps': ['Your daily account can do normal work without a password. Installing software, updating the system, and changing some settings need admin rights.', 'When a dialog asks for your password, that is usually PolicyKit — GUI apps requesting temporary admin rights. Type your login password.', 'In the Terminal, <code>sudo</code> means “do this as superuser.” Example: <code>sudo apt update</code>. You type your password; nothing appears as you type.', 'sudo remembers you for a short time so you are not prompted every second. When in doubt, close the terminal when finished with admin tasks.'], 'html_file': 'html/lessons/09-sudo.html', 'keywords': 'safe vs sudo / password prompts when ubuntu asks for your password, what sudo means, and how to stay safe. getting comfortable your daily account can do normal work without a password. installing software, updating the system, and changing some settings need admin rights. when a dialog asks for your password, that is usually policykit — gui apps requesting temporary admin rights. type your login password.'}, {'id': '10-browser-email', 'num': 10, 'level': 'comfortable', 'level_label': 'Getting comfortable', 'title': 'Browser, email, printers', 'summary': 'Firefox (and friends), webmail or Thunderbird, and adding a printer.', 'steps': ['Firefox is usually preinstalled. Open it from the dock. Sign into bookmarks sync if you used Firefox on Windows.', 'Chromium or Google Chrome can be installed from App Center / Flathub if you prefer.', 'Email: use Gmail/Outlook in the browser, or install Thunderbird for a desktop client.', 'Printers: Settings → Printers → Add Printer. Many network printers appear automatically. For others, install the maker’s Linux driver or use IPP.'], 'html_file': 'html/lessons/10-browser-email.html', 'keywords': 'browser, email, printers firefox (and friends), webmail or thunderbird, and adding a printer. getting comfortable firefox is usually preinstalled. open it from the dock. sign into bookmarks sync if you used firefox on windows. chromium or google chrome can be installed from app center / flathub if you prefer.'}, {'id': '11-backups', 'num': 11, 'level': 'comfortable', 'level_label': 'Getting comfortable', 'title': 'Backups', 'summary': 'Timeshift for system snapshots and a simple “copy important files” habit.', 'steps': ['Decide what matters: Documents, Photos, browser bookmarks export, project folders.', 'Simple file backup: plug in a USB drive or use a cloud folder; copy Home folders you care about. Schedule a calendar reminder monthly.', 'Timeshift (popular on Ubuntu): install from App Center or apt, then create rsync/snapshot backups before big upgrades. Restore if an update goes wrong.', 'Test a restore once — a backup you never tested is a wish, not a plan.'], 'html_file': 'html/lessons/11-backups.html', 'keywords': 'backups timeshift for system snapshots and a simple “copy important files” habit. getting comfortable decide what matters: documents, photos, browser bookmarks export, project folders. simple file backup: plug in a usb drive or use a cloud folder; copy home folders you care about. schedule a calendar reminder monthly.'}, {'id': '12-troubleshoot', 'num': 12, 'level': 'comfortable', 'level_label': 'Getting comfortable', 'title': 'Troubleshooting checklist', 'summary': 'No internet, stuck updates, and slow boot — calm first steps.', 'steps': ['Stay calm. Write down what changed last (new app, update, cable).', 'No internet: toggle airplane mode, reconnect Wi‑Fi, try Ethernet, reboot the router, check Settings → Network.', 'Stuck update: wait a few minutes; check if Software Updater is waiting for a password behind another window. Reboot and retry. Avoid force-killing dpkg unless a trusted guide says so.', 'Slow boot: note whether it is firmware, disk, or login. Free disk space in Home; disable unneeded startup apps in Settings → Apps → Startup.'], 'html_file': 'html/lessons/12-troubleshoot.html', 'keywords': 'troubleshooting checklist no internet, stuck updates, and slow boot — calm first steps. getting comfortable stay calm. write down what changed last (new app, update, cable). no internet: toggle airplane mode, reconnect wi‑fi, try ethernet, reboot the router, check settings → network.'}, {'id': '13-package-types', 'num': 13, 'level': 'novice', 'level_label': 'Novice', 'title': 'Flatpak vs apt vs Snap', 'summary': 'Three common ways software is packaged on Ubuntu — when to use which.', 'steps': ['apt / .deb: Ubuntu’s classic packages. Best for system tools and anything a guide says to <code>apt install</code>.', 'Snap: Canonical’s containerized packages. Some apps in App Center are Snaps (Firefox often is). They update themselves in the background.', 'Flatpak: another sandboxed format; Flathub is the big store. Great for desktop apps (GIMP, OBS, many games tools).', 'Pick one source per app to avoid duplicates. If App Center offers both, read whether you want sandboxing or classic integration.'], 'html_file': 'html/lessons/13-package-types.html', 'keywords': 'flatpak vs apt vs snap three common ways software is packaged on ubuntu — when to use which. novice apt / .deb: ubuntu’s classic packages. best for system tools and anything a guide says to <code>apt install</code>. snap: canonical’s containerized packages. some apps in app center are snaps (firefox often is). they update themselves in the background.'}, {'id': '14-gaming', 'num': 14, 'level': 'novice', 'level_label': 'Novice', 'title': 'Steam + Proton / gaming intro', 'summary': 'Install Steam, enable Proton, and set expectations for Windows games on Ubuntu.', 'steps': ['Install Steam from App Center or the official .deb from Valve’s site. Sign in.', 'Steam Play / Proton: Steam → Settings → Compatibility → enable Steam Play for supported (and optionally all) titles.', 'Check ProtonDB.com for your game’s reports before buying or installing.', 'GPU drivers: for NVIDIA, Settings → Additional Drivers often offers the proprietary driver — install, reboot, then test.'], 'html_file': 'html/lessons/14-gaming.html', 'keywords': 'steam + proton / gaming intro install steam, enable proton, and set expectations for windows games on ubuntu. novice install steam from app center or the official .deb from valve’s site. sign in. steam play / proton: steam → settings → compatibility → enable steam play for supported (and optionally all) titles.'}, {'id': '15-permissions', 'num': 15, 'level': 'novice', 'level_label': 'Novice', 'title': 'Permissions, users, Disks overview', 'summary': 'Read/write/execute in plain English, extra users, and the Disks utility.', 'steps': ['Every file has an owner and permissions: read, write, execute. That is why some folders need sudo.', 'Settings → Users: add another person a separate account so their files stay private.', 'Open Disks (gnome-disk-utility): see drives, partitions, and mount points. Useful to check a USB or second SSD.', 'Do not Format a disk unless you intend to erase it. Double-check the device name.'], 'html_file': 'html/lessons/15-permissions.html', 'keywords': 'permissions, users, disks overview read/write/execute in plain english, extra users, and the disks utility. novice every file has an owner and permissions: read, write, execute. that is why some folders need sudo. settings → users: add another person a separate account so their files stay private.'}, {'id': '16-customize', 'num': 16, 'level': 'novice', 'level_label': 'Novice', 'title': 'Customizing look', 'summary': 'Appearance, wallpaper, accents — including dark Yaru with an orange accent tip.', 'steps': ['Open Settings → Appearance (or Ubuntu Desktop on some versions).', 'Choose Light or Dark style. Yaru is Ubuntu’s default theme family.', 'Set an accent color — orange matches Ubuntu’s classic brand and this tutorial’s accent.', 'Change wallpaper: Appearance → background, or right-click the desktop → Change Background.'], 'html_file': 'html/lessons/16-customize.html', 'keywords': 'customizing look appearance, wallpaper, accents — including dark yaru with an orange accent tip. novice open settings → appearance (or ubuntu desktop on some versions). choose light or dark style. yaru is ubuntu’s default theme family.'}, {'id': '17-next-steps', 'num': 17, 'level': 'novice', 'level_label': 'Novice', 'title': 'Next steps / learning path', 'summary': 'Where to go after these 17 lessons — practice projects and trusted resources.', 'steps': ['Practice: install one app from App Center, one Flatpak, and run <code>sudo apt update && sudo apt upgrade</code> once this week.', 'Make a Timeshift snapshot (or copy Documents to USB) before your next big change.', 'Skim the official Ubuntu desktop docs and ask questions on Ask Ubuntu — search first, then post clearly.', 'Optional next skills: basic bash scripting, git, Docker, or a programming language — only when the desktop feels boringly reliable.'], 'html_file': 'html/lessons/17-next-steps.html', 'keywords': 'next steps / learning path where to go after these 17 lessons — practice projects and trusted resources. novice practice: install one app from app center, one flatpak, and run <code>sudo apt update && sudo apt upgrade</code> once this week. make a timeshift snapshot (or copy documents to usb) before your next big change.'}]


def filter_lessons(category="all", query=""):
    q = (query or "").strip().lower()
    out = []
    for lesson in LESSONS:
        if category != "all" and lesson["level"] != category:
            continue
        if q and q not in lesson.get("keywords", "") and q not in lesson["title"].lower() and q not in lesson["summary"].lower():
            continue
        out.append(lesson)
    return out


def get_lesson(lesson_id):
    for lesson in LESSONS:
        if lesson["id"] == lesson_id:
            return lesson
    return None
